 static void Audit(){var lines=new List<string>();foreach(string scene in new[]{"AmazoniaTerrestre","AmazoniaAcuatica"}){EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");int missing=0,broken=0;foreach(var root in SceneManager.GetActiveScene().GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true)){missing+=GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject);foreach(var c in t.GetComponents<Component>()){if(c==null)continue;var so=new SerializedObject(c);var prop=so.GetIterator();while(prop.NextVisible(true))if(prop.propertyType==SerializedPropertyType.ObjectReference&&prop.objectReferenceValue==null&&prop.objectReferenceEntityIdValue!=default)broken++;}}lines.Add(scene+": Missing Scripts="+missing+", Missing References="+broken);if(missing+broken>0)throw new Exception(scene+" referencias rotas");}File.WriteAllLines("Documentation/V2/Auditoria.txt",lines);}
 static void Mode(PlayModeStateChange state){if(state==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("V2Tests",false)){SessionState.SetBool("V2Tests",false);results.Clear();errors.Clear();previous=Keyboard.current;keyboard=InputSystem.AddDevice<Keyboard>();keyboard.MakeCurrent();oldBehavior=InputSystem.settings.backgroundBehavior;oldBackground=Application.runInBackground;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;Application.runInBackground=true;Application.logMessageReceived+=Log;routine=Suite();resume=0;}if(state==PlayModeStateChange.ExitingPlayMode&&routine!=null)Finish("Interrumpido");}
